<?php $page_title='Add Patient';require_once __DIR__.'/../includes/header.php';if($_SERVER['REQUEST_METHOD']==='POST'){$code='PT'.date('ymd').rand(100,999);$pdo->prepare("INSERT INTO patients(patient_code,name,gender,dob,age,phone,email,blood_group,address,emergency_contact) VALUES(?,?,?,?,?,?,?,?,?,?)")->execute([$code,$_POST['name'],$_POST['gender'],$_POST['dob'],$_POST['age'],$_POST['phone'],$_POST['email'],$_POST['blood_group'],$_POST['address'],$_POST['emergency_contact']]);header('Location:index.php');exit;}?>
<h2>Add Patient</h2><div class="card p-4 mt-3"><form method="post"><div class="row g-3"><?php $fields=['name'=>'Full Name','dob'=>'Date of Birth','age'=>'Age','phone'=>'Phone','email'=>'Email','blood_group'=>'Blood Group','address'=>'Address','emergency_contact'=>'Emergency Contact'];foreach($fields as $n=>$l):?><div class="col-md-6"><label><?=$l?></label><input name="<?=$n?>" class="form-control" <?=$n==='name'?'required':''?> <?=$n==='dob'?'type="date"':''?>></div><?php endforeach;?><div class="col-md-6"><label>Gender</label><select name="gender" class="form-select"><option>Male</option><option>Female</option><option>Other</option></select></div></div><button class="btn btn-primary mt-3">Save Patient</button></form></div><?php require_once __DIR__.'/../includes/footer.php';?>